bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import pg from 'pg';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const env=process.env;
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),database:'videobot',max:1,connectionTimeoutMillis:4000});
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
try{
 const q=await pool.query("SELECT p.pack_name,p.owner_user_id,COUNT(i.file_id)::int AS db_count FROM videobot_sticker_packs p LEFT JOIN videobot_sticker_items i ON i.pack_name=p.pack_name WHERE p.status='active' GROUP BY p.pack_name,p.owner_user_id ORDER BY db_count DESC,p.updated_at DESC LIMIT 1");
 if(q.rowCount!==1)process.exit(85);
 const p=q.rows[0];
 const pend=await pool.query("SELECT COUNT(*)::int AS n FROM videobot_sticker_registration_receipts WHERE owner_user_id=$1 AND phase='needs_reconcile'",[p.owner_user_id]);
 if(pend.rows[0].n>0)process.exit(81);
 const r=await fetch('https://api.telegram.org/bot'+token+'/getStickerSet',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:p.pack_name}),signal:AbortSignal.timeout(7000)});
 const result=await r.json();
 if(!result.ok||!Array.isArray(result.result?.stickers))process.exit(83);
 const telegramCount=result.result.stickers.length;
 if(telegramCount!==p.db_count)process.exit(82);
 if(telegramCount<5)process.exit(84);
 console.log('STICKER_FIFTH_ITEM_TELEGRAM_DB=PASS');
}catch{process.exitCode=86;}finally{await pool.end();}
NODE
